def steps(start, stop, stride=1, include_stop=False):
    if stride < 1:
        raise ValueError('positive stride required')
    direction = (1 if stop >= start else -1) * stride
    end = stop + (1 if include_stop and direction > 0 else -1 if include_stop and direction < 0 else 0)
    return list(range(start, end, direction))

